-- Economics Gen2 T1 Practice rebalancing: 20 easy / 30 medium / 20 hard.
-- Original questions never deleted; originals with historical references remain resolvable.
-- New question versions carry their own complete trilingual content and per-option diagnostics.
-- Preconditions and postconditions are enforced transactionally. Run controlled QA transaction first.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '90s';
DO $reb$
DECLARE
  payload jsonb := '[{"ref":"EC9708:G2:EC9708-G2-T1-P-001","d":"hard","sec":180,"k":"B","en":"An economy can move from A (60 units of food, 20 machines) to B (45 food, 30 machines), then to C (20 food, 40 machines). How much greater is the opportunity cost in food per extra machine on B→C than on A→B?","ru":"Экономика может перейти от A (60 единиц продовольствия, 20 машин) к B (45 единиц продовольствия, 30 машин), затем к C (20 единиц продовольствия, 40 машин). На сколько единиц продовольствия альтернативная стоимость одной дополнительной машины на участке B→C больше, чем на A→B?","uz":"Iqtisodiyot A (60 birlik oziq-ovqat, 20 ta mashina) nuqtadan B (45 birlik oziq-ovqat, 30 ta mashina) ga, keyin C (20 birlik oziq-ovqat, 40 ta mashina) ga o‘tadi. B→C oralig‘ida bitta qo‘shimcha mashinaning oziq-ovqatdagi muqobil qiymati A→B ga nisbatan qancha yuqori?","options_en":["0.5","1.0","1.5","2.5"],"options_ru":["0.5","1.0","1.5","2.5"],"options_uz":["0.5","1.0","1.5","2.5"],"why":["The first trade-off is 15/10 = 1.5 food per machine; the second is 25/10 = 2.5. The difference is 1.0.","На первом участке потери составляют 15/10 = 1,5 единицы продовольствия на машину; на втором — 25/10 = 2,5. Разница равна 1,0.","Birinchi oraliqda yo‘qotish 15/10 = 1,5 birlik oziq-ovqat, ikkinchisida 25/10 = 2,5. Farq 1,0 ga teng."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-002","d":"hard","sec":180,"k":"D","en":"Demand for a product is initially 400 units. Real income rises by 10% (YED = +1.2), while the price of a substitute rises by 5% (XED = +0.8). Assume the two estimated percentage effects are additive and other factors are fixed. What is the new quantity demanded?","ru":"Первоначальный спрос на товар составляет 400 единиц. Реальный доход растёт на 10% (YED = +1,2), а цена заменителя — на 5% (XED = +0,8). Считайте, что два процентных эффекта складываются, прочие факторы неизменны. Каким станет объём спроса?","uz":"Mahsulotga dastlabki talab 400 birlik. Real daromad 10% ga oshadi (YED = +1,2), o‘rinbosar mahsulot narxi esa 5% ga oshadi (XED = +0,8). Ikki foizli ta’sir qo‘shiladi, boshqa omillar o‘zgarmaydi deb oling. Yangi talab miqdori qancha?","options_en":["416","448","460","464"],"options_ru":["416","448","460","464"],"options_uz":["416","448","460","464"],"why":["Income adds 12% and the substitute''s price adds 4% to demand, making a 16% increase: 400 × 1.16 = 464.","Рост дохода добавляет к спросу 12%, повышение цены заменителя — ещё 4%. Всего +16%: 400 × 1,16 = 464.","Daromad ta’siri talabni 12% ga, o‘rinbosar narxi esa yana 4% ga oshiradi. Jami +16%: 400 × 1,16 = 464."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-003","d":"hard","sec":180,"k":"B","en":"Three households value a shared flood-warning system at $45, $40 and $35 respectively. The system costs $100 and everyone benefits whether or not they pay. Which economic conclusion follows from these figures?","ru":"Три домохозяйства оценивают общую систему предупреждения о наводнении соответственно в $45, $40 и $35. Система стоит $100; её преимуществами пользуются все независимо от оплаты. Какой экономический вывод следует из этих данных?","uz":"Uchta xonadon umumiy toshqin haqida ogohlantirish tizimini mos ravishda $45, $40 va $35 ga baholaydi. Tizim $100 turadi, uning foydasidan to‘lagan-to‘lamaganidan qat’i nazar hamma foydalanadi. Qaysi iqtisodiy xulosa kelib chiqadi?","options_en":["Total benefit is $80, so provision destroys $20 of value.","Total benefit exceeds cost by $20, although voluntary funding may fail due to free riding.","The system is a private good because each household values it differently.","Only the household valuing it at $45 should pay the entire cost."],"options_ru":["Общая выгода равна $80, поэтому система уничтожает $20 ценности.","Общая выгода превышает затраты на $20, хотя добровольное финансирование может не сработать из-за безбилетников.","Это частное благо, поскольку домохозяйства оценивают его по-разному.","Всю стоимость должно оплатить только домохозяйство, оценивающее систему в $45."],"options_uz":["Umumiy foyda $80; demak, tizim $20 qiymatni yo‘qotadi.","Umumiy foyda xarajatdan $20 yuqori, biroq tekin foydalanish muammosi tufayli ixtiyoriy moliyalashtirish yetishmasligi mumkin.","Har bir xonadon turlicha baholagani uchun bu xususiy ne’mat.","Butun xarajatni tizimni $45 ga baholagan xonadon to‘lashi kerak."],"why":["Combined benefit is $120 against a $100 cost, so net social benefit is $20. Non-excludability creates incentives to free ride, which can impede voluntary funding.","Суммарная выгода $120 при затратах $100: общественная чистая выгода $20. Неисключаемость создаёт стимул пользоваться благом без оплаты.","Umumiy foyda $120, xarajat $100; sof ijtimoiy foyda $20. Istisno qilib bo‘lmaslik tekin foydalanishni rag‘batlantiradi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-005","d":"hard","sec":165,"k":"C","en":"A sugary drink is heavily consumed because buyers underestimate its future personal health costs. A study finds no measurable costs imposed on third parties. Which assessment is most defensible?","ru":"Сладкий напиток потребляют в избытке, потому что покупатели недооценивают будущий вред собственному здоровью. Исследование не выявило измеримых затрат для третьих лиц. Какая оценка наиболее обоснованна?","uz":"Shirin ichimlik haddan tashqari ko‘p iste’mol qilinadi, chunki xaridorlar o‘z sog‘lig‘iga kelajakdagi zararini yetarli baholamaydilar. Tadqiqot uchinchi shaxslarga o‘lchanadigan zarar topmadi. Qaysi xulosa eng asosli?","options_en":["The case proves a negative externality equal to private health costs.","The drink is a pure public good because health information matters.","Imperfect information can cause overconsumption of a demerit good without proving an external cost.","Every informed buyer would necessarily stop consuming the drink."],"options_ru":["Случай доказывает отрицательный внешний эффект, равный личному вреду здоровью.","Напиток является чистым общественным благом, поскольку информация о здоровье важна.","Недостаток информации может вызывать избыточное потребление нежелательного блага и без доказанного внешнего ущерба.","Каждый информированный покупатель обязательно полностью откажется от напитка."],"options_uz":["Bu holat shaxsiy salomatlik xarajatlariga teng salbiy tashqi ta’sirni isbotlaydi.","Salomatlik haqidagi axborot muhim bo‘lgani uchun ichimlik sof jamoat ne’matidir.","Axborot yetishmasligi salbiy ne’matning ortiqcha iste’moliga, tashqi zarar isbotlanmasa ham, olib kelishi mumkin.","To‘liq ma’lumot olgan har bir xaridor ichimlikdan albatta butunlay voz kechadi."],"why":["Private costs borne by the consumer are not automatically external costs. Underestimated private harm supports an information-based explanation of demerit-good overconsumption.","Личный вред потребителя сам по себе не является внешним ущербом. Недооценка этого вреда объясняет избыточное потребление при несовершенной информации.","Iste’molchining shaxsiy zarari avtomatik ravishda tashqi zarar emas. Uni kam baholash axborot yetishmasligi orqali ortiqcha iste’molni tushuntiradi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-007","d":"hard","sec":165,"k":"A","en":"An economy starts inside its PPC because labour is unemployed. It then employs its idle workers; separately, a farming innovation increases the maximum possible food output but leaves machinery technology unchanged. Which pair correctly describes the two changes?","ru":"Экономика первоначально находится внутри КПВ из-за безработицы. Затем она вовлекает свободных работников; отдельно новая сельскохозяйственная технология увеличивает максимально возможный выпуск продовольствия, не меняя технологию производства машин. Какая пара правильно описывает эти изменения?","uz":"Iqtisodiyot ishsizlik tufayli ishlab chiqarish imkoniyatlari egri chizig‘ining (IIEC) ichida joylashgan. Keyin bo‘sh ishchilar ishga jalb etiladi; alohida agrar yangilik oziq-ovqatning maksimal ishlab chiqarilishini oshiradi, mashina texnologiyasi o‘zgarmaydi. Qaysi juftlik to‘g‘ri?","options_en":["Movement towards the existing PPC; outward pivot at the food intercept.","Outward parallel shift of the PPC; movement along the old curve.","Movement outside the old PPC; inward shift at both intercepts.","No change in actual production; a leftward shift of the machinery intercept."],"options_ru":["Движение к существующей КПВ; поворот КПВ наружу у оси продовольствия.","Параллельный сдвиг КПВ наружу; движение вдоль старой кривой.","Выход за прежнюю КПВ без роста возможностей; сдвиг обоих пересечений внутрь.","Отсутствие изменения выпуска; сдвиг пересечения с осью машин влево."],"options_uz":["Mavjud IIEC chegarasiga yaqinlashish; oziq-ovqat o‘qidagi kesishish nuqtasining tashqariga siljishi.","IIECning parallel tashqariga siljishi; eski egri chiziq bo‘ylab harakat.","Imkoniyat oshmasdan eski IIECdan tashqariga chiqish; ikkala kesishishning ichkariga siljishi.","Haqiqiy ishlab chiqarish o‘zgarmaydi; mashina o‘qidagi kesishish chapga siljiydi."],"why":["Using idle resources raises actual output without changing capacity. A sector-specific technological improvement expands the frontier only on the food side.","Использование простаивающих ресурсов повышает фактический выпуск без изменения потенциала. Отраслевой технологический прогресс расширяет границу со стороны продовольствия.","Bo‘sh resurslarni ishga solish imkoniyat chegarasini o‘zgartirmasdan ishlab chiqarishni oshiradi; tarmoq innovatsiyasi chegarani oziq-ovqat tomon kengaytiradi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-011","d":"hard","sec":195,"k":"A","en":"At an initial common price, producer X supplies 100 units with PES 2.0, and producer Y supplies 300 units with PES 0.5. Price rises by 10%. Using the given percentage-change approximations, what is the market PES based on the combined supply?","ru":"При первоначальной общей цене производитель X поставляет 100 единиц с PES 2,0, а производитель Y — 300 единиц с PES 0,5. Цена растёт на 10%. Используя приближение процентных изменений, найдите PES общего предложения рынка.","uz":"Boshlang‘ich umumiy narxda X ishlab chiqaruvchi 100 birlikni PES 2,0 bilan, Y esa 300 birlikni PES 0,5 bilan taklif qiladi. Narx 10% ga oshadi. Berilgan foizli o‘zgarishlar yaqinlashuvida jami bozor taklifining PES qiymati qancha?","options_en":["0.875","1.25","1.50","2.50"],"options_ru":["0.875","1.25","1.50","2.50"],"options_uz":["0.875","1.25","1.50","2.50"],"why":["X adds 20 units and Y adds 15, so market supply rises 35/400 = 8.75%. PES = 8.75%/10% = 0.875, not the simple average of individual elasticities.","X добавляет 20 единиц, Y — 15. Рыночное предложение растёт на 35/400 = 8,75%; PES = 8,75%/10% = 0,875, а не среднему индивидуальных эластичностей.","X 20 birlik, Y 15 birlik qo‘shadi; bozor taklifi 35/400 = 8,75% ga oshadi. PES = 8,75%/10% = 0,875; oddiy o‘rtacha olinmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-013","d":"hard","sec":170,"k":"D","en":"An economy''s linear PPC initially runs from 100 units of food (zero machines) to 50 machines (zero food). Better machinery technology raises only the machine intercept to 80. At food output of 50 units, how many additional machines can now be produced efficiently compared with the original PPC?","ru":"Первоначально линейная КПВ идёт от 100 единиц продовольствия (0 машин) до 50 машин (0 продовольствия). Улучшение технологии производства машин увеличивает только максимум машин до 80. На сколько больше машин теперь можно эффективно произвести при выпуске 50 единиц продовольствия?","uz":"Iqtisodiyotning chiziqli IIECsi dastlab 100 birlik oziq-ovqat (0 mashina) va 50 mashina (0 oziq-ovqat) nuqtalaridan o‘tadi. Mashina texnologiyasi faqat mashina maksimumini 80 taga oshiradi. 50 birlik oziq-ovqat ishlab chiqarilganda avvalgidan nechta ko‘p mashina ishlab chiqarish mumkin?","options_en":["5","10","25","15"],"options_ru":["5","10","25","15"],"options_uz":["5","10","25","15"],"why":["At 50 food, the original linear PPC permits 25 machines, while the new one permits 40. The increase is 15 machines.","При 50 единицах продовольствия прежняя линейная КПВ допускает 25 машин, новая — 40. Прирост равен 15.","50 birlik oziq-ovqatda eski chiziqli IIEC 25 ta, yangisi 40 ta mashinaga imkon beradi. Farq 15 ta."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-014","d":"hard","sec":190,"k":"C","en":"At any non-negative price P in the relevant range, two buyers demand Q1 = 60 − 2P and Q2 = 40 − P. Market supply is Qs = 10 + P. What are the equilibrium price and total quantity?","ru":"При неотрицательной цене P в рассматриваемом диапазоне спрос двух покупателей: Q1 = 60 − 2P и Q2 = 40 − P. Рыночное предложение: Qs = 10 + P. Найдите равновесную цену и общий объём.","uz":"Tegishli diapazondagi manfiy bo‘lmagan P narxda ikki xaridor talabi Q1 = 60 − 2P va Q2 = 40 − P. Bozor taklifi Qs = 10 + P. Muvozanat narxi va umumiy miqdori qanday?","options_en":["P = 30; Q = 40","P = 20; Q = 30","P = 22.5; Q = 32.5","P = 25; Q = 35"],"options_ru":["P = 30; Q = 40","P = 20; Q = 30","P = 22.5; Q = 32.5","P = 25; Q = 35"],"options_uz":["P = 30; Q = 40","P = 20; Q = 30","P = 22.5; Q = 32.5","P = 25; Q = 35"],"why":["Horizontal addition gives Qd = 100 − 3P. Equate with Qs = 10 + P: 90 = 4P, so P = 22.5 and Q = 32.5.","Горизонтальное сложение даёт Qd = 100 − 3P. Приравниваем к Qs = 10 + P: 90 = 4P, поэтому P = 22,5, Q = 32,5.","Gorizontal qo‘shish bilan Qd = 100 − 3P. Qs = 10 + P ga tenglashtiramiz: 90 = 4P; P = 22,5 va Q = 32,5."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-016","d":"hard","sec":195,"k":"B","en":"Market demand is initially Qd = 150 − 2P and supply is Qs = 30 + P. After a demand increase, Qd becomes 180 − 2P; improved production also shifts supply to Qs = 45 + P. What are the changes in equilibrium price and quantity?","ru":"Первоначально рыночный спрос Qd = 150 − 2P, предложение Qs = 30 + P. После роста спроса Qd = 180 − 2P; улучшение производства одновременно меняет предложение на Qs = 45 + P. Как изменятся равновесные цена и объём?","uz":"Dastlab bozor talabi Qd = 150 − 2P, taklif Qs = 30 + P. Talab oshgach Qd = 180 − 2P bo‘ladi; ishlab chiqarish yaxshilangani uchun taklif ham Qs = 45 + P ga o‘zgaradi. Muvozanat narxi va miqdori qanday o‘zgaradi?","options_en":["Price +10, quantity +10","Price +5, quantity +20","Price −5, quantity +20","Price +5, quantity +5"],"options_ru":["Цена +10, объём +10","Цена +5, объём +20","Цена −5, объём +20","Цена +5, объём +5"],"options_uz":["Narx +10, miqdor +10","Narx +5, miqdor +20","Narx −5, miqdor +20","Narx +5, miqdor +5"],"why":["Originally 150 − 2P = 30 + P gives P = 40 and Q = 70. Afterwards 180 − 2P = 45 + P gives P = 45 and Q = 90: +5 and +20.","Сначала P = 40, Q = 70. После двух изменений P = 45, Q = 90. Значит, цена растёт на 5, объём — на 20.","Avval P = 40, Q = 70. Ikkala o‘zgarishdan so‘ng P = 45, Q = 90. Narx +5, miqdor +20."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-020","d":"hard","sec":180,"k":"C","en":"Tea demand is initially 500 packs. A 10% rise in coffee''s price raises tea demand (XED = +0.8), while a simultaneous 5% increase in tea''s own price reduces tea quantity demanded (PED = −1.2). Assume the first-order percentage effects add. What is the new quantity of tea demanded?","ru":"Первоначальный спрос на чай — 500 упаковок. Подорожание кофе на 10% повышает спрос на чай (XED = +0,8), а одновременное повышение цены самого чая на 5% снижает его объём спроса (PED = −1,2). Считайте, что процентные эффекты первого порядка складываются. Найдите новый объём спроса на чай.","uz":"Choyga dastlabki talab 500 qadoq. Qahva narxining 10% ga oshishi choy talabini ko‘paytiradi (XED = +0,8), choyning o‘z narxi 5% ga oshishi esa talab miqdorini kamaytiradi (PED = −1,2). Birinchi tartibli foizli ta’sirlar qo‘shiladi deb oling. Choyga yangi talab qancha?","options_en":["430","500","510","540"],"options_ru":["430","500","510","540"],"options_uz":["430","500","510","540"],"why":["The substitute-price effect is +8% and the own-price effect is −6%. Net +2% gives 500 × 1.02 = 510.","Повышение цены заменителя даёт +8%, изменение собственной цены — −6%. Итог +2%: 500 × 1,02 = 510.","O‘rinbosar narxi ta’siri +8%, o‘z narxi ta’siri −6%. Sof +2%: 500 × 1,02 = 510."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-022","d":"hard","sec":180,"k":"A","en":"A petrol market initially has demand Qd = 180 − 3P and supply Qs = 20 + P. A new metro system reduces petrol demand to Qd = 150 − 3P, while more efficient refining increases supply to Qs = 30 + P. Relative to the initial equilibrium, what happens?","ru":"Первоначально спрос на бензин Qd = 180 − 3P, предложение Qs = 20 + P. Новое метро снижает спрос до Qd = 150 − 3P, а более эффективная переработка увеличивает предложение до Qs = 30 + P. Что происходит относительно первоначального равновесия?","uz":"Benzin bozorida dastlab talab Qd = 180 − 3P va taklif Qs = 20 + P. Yangi metro talabni Qd = 150 − 3P ga kamaytiradi, samarali qayta ishlash esa taklifni Qs = 30 + P ga oshiradi. Dastlabki muvozanatga nisbatan nima yuz beradi?","options_en":["Price falls by 10; quantity is unchanged","Price falls by 10; quantity rises by 10","Price rises by 10; quantity is unchanged","Price falls by 5; quantity falls by 10"],"options_ru":["Цена снижается на 10; объём не меняется","Цена снижается на 10; объём повышается на 10","Цена повышается на 10; объём не меняется","Цена снижается на 5; объём falls by 10"],"options_uz":["Narx ga kamayadi 10; miqdor o‘zgarmaydi","Narx ga kamayadi 10; miqdor ga oshadi 10","Narx ga oshadi 10; miqdor o‘zgarmaydi","Narx ga kamayadi 5; miqdor falls by 10"],"why":["Initially P = 40, Q = 60; after both changes P = 30, Q = 60. Two curve shifts affect price but offset each other in quantity.","Сначала P = 40, Q = 60; после двух сдвигов P = 30, Q = 60. Цена уменьшается на 10, объём не меняется.","Avval P = 40, Q = 60; ikkala siljishdan keyin P = 30, Q = 60. Narx 10 ga pasayadi, miqdor o‘zgarmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-024","d":"hard","sec":180,"k":"D","en":"Initially, rail demand is Qd = 100 − 2P and supply is Qs = 20 + 2P. Higher bus fares raise rail demand to Qd = 120 − 2P, but track maintenance reduces rail supply to Qs = 10 + 2P. What are the changes in rail equilibrium price and quantity?","ru":"Первоначально спрос на поездки поездом Qd = 100 − 2P, предложение Qs = 20 + 2P. Рост автобусных тарифов увеличивает спрос на поездки поездом до Qd = 120 − 2P, но ремонт путей уменьшает предложение до Qs = 10 + 2P. Как изменятся равновесные цена и объём?","uz":"Dastlab temiryo‘l safarlariga talab Qd = 100 − 2P, taklif Qs = 20 + 2P. Avtobus narxlari oshishi talabni Qd = 120 − 2P ga ko‘paytiradi, yo‘l ta’miri esa taklifni Qs = 10 + 2P ga kamaytiradi. Muvozanat narxi va miqdori qanday o‘zgaradi?","options_en":["Price +5, quantity +10","Price +7.5, quantity −5","Price +10, quantity +5","Price +7.5, quantity +5"],"options_ru":["Цена +5, объём +10","Цена +7.5, объём −5","Цена +10, объём +5","Цена +7.5, объём +5"],"options_uz":["Narx +5, miqdor +10","Narx +7.5, miqdor −5","Narx +10, miqdor +5","Narx +7.5, miqdor +5"],"why":["Originally P = 20, Q = 60. Afterwards P = 27.5 and Q = 65. Thus price rises by 7.5 and quantity by 5.","Сначала P = 20, Q = 60; после изменений P = 27,5, Q = 65. Цена выросла на 7,5, объём — на 5.","Avval P = 20, Q = 60; keyin P = 27,5, Q = 65. Narx 7,5 ga, miqdor 5 ga oshadi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-025","d":"hard","sec":190,"k":"C","en":"On a straight-line demand curve P = 100 − 2Q, the market moves from Q = 20 to Q = 30. Using the midpoint method, which pair correctly gives the magnitude of PED over this interval and the effect on total revenue?","ru":"На линейной кривой спроса P = 100 − 2Q рынок переходит от Q = 20 к Q = 30. Используя метод средней точки, выберите правильную пару: модуль PED на участке и изменение общей выручки.","uz":"Chiziqli talab egri chizig‘i P = 100 − 2Q bo‘yicha bozor Q = 20 dan Q = 30 ga o‘tadi. O‘rta nuqta usulida ushbu oraliqdagi PED moduli va umumiy tushum o‘zgarishi qanday?","options_en":["PED = 0.5; revenue rises by $200","PED = 2; revenue falls by $200","PED = 1; total revenue is unchanged","PED = 1; revenue rises by $200"],"options_ru":["PED = 0,5; выручка выросла на $200","PED = 2; выручка упала на $200","PED = 1; общая выручка не изменилась","PED = 1; выручка выросла на $200"],"options_uz":["PED = 0,5; tushum $200 ga oshdi","PED = 2; tushum $200 ga kamaydi","PED = 1; umumiy tushum o‘zgarmadi","PED = 1; tushum $200 ga oshdi"],"why":["Prices are $60 and $40; both price–quantity products equal $1,200. Midpoint PED is (10/25)/(20/50) = 1.","Цены равны $60 и $40, в обоих случаях общая выручка $1 200. PED по средней точке: (10/25)/(20/50) = 1.","Narxlar $60 va $40; har ikkala holatda tushum $1200. O‘rta nuqta usulidagi PED: (10/25)/(20/50) = 1."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-029","d":"hard","sec":180,"k":"A","en":"Demand for a product is initially 500 units. Real household income rises 10% (YED = +1.5), while its own price simultaneously rises 5% (PED = −0.8). Assume additive first-order percentage effects with other influences fixed. What quantity is now predicted?","ru":"Первоначальный спрос на товар — 500 единиц. Реальный доход домохозяйств растёт на 10% (YED = +1,5), а цена самого товара одновременно растёт на 5% (PED = −0,8). Считайте процентные эффекты первого порядка аддитивными, прочие условия неизменными. Каков прогноз спроса?","uz":"Mahsulotga dastlabki talab 500 birlik. Uy xo‘jaliklarining real daromadi 10% ga oshadi (YED = +1,5), mahsulotning o‘z narxi esa bir vaqtda 5% ga oshadi (PED = −0,8). Birinchi tartibli foizli ta’sirlar qo‘shiladi, boshqa omillar o‘zgarmaydi deb oling. Talab qancha?","options_en":["555","575","520","480"],"options_ru":["555","575","520","480"],"options_uz":["555","575","520","480"],"why":["Income increases demand 15%; the own-price rise reduces quantity demanded 4%. Net +11% on 500 gives 555.","Доход повышает спрос на 15%, рост собственной цены уменьшает его объём на 4%. Итого +11% от 500 = 555.","Daromad talabni 15% oshiradi, narxning o‘zgarishi uni 4% kamaytiradi. Sof +11%: 500 × 1,11 = 555."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-033","d":"hard","sec":165,"k":"B","en":"A preventive screening programme costs $60 per patient. Each patient privately values the benefit at $25, while additional benefits to other people are estimated at $50 per patient. Assume these values can be added. Which conclusion about provision is best supported?","ru":"Профилактическое обследование стоит $60 на пациента. Личную пользу пациент оценивает в $25, дополнительная выгода для других людей составляет примерно $50 на пациента. Считайте эти оценки суммируемыми. Какой вывод о предоставлении услуги наиболее обоснован?","uz":"Profilaktik tekshiruv har bir bemor uchun $60 turadi. Bemorning shaxsiy foydasi $25, boshqa odamlarga qo‘shimcha foyda esa har bir bemor uchun $50 deb baholanadi. Ushbu qiymatlar qo‘shiladi deb oling. Xizmatni taqdim etish haqida qaysi xulosa asosli?","options_en":["Private willingness to pay exceeds the cost, so no underconsumption is possible.","The combined benefit exceeds cost by $15, but private demand alone may be too low.","There is a net social loss of $35 per patient.","The service must be a pure public good because outsiders benefit."],"options_ru":["Личная готовность платить превышает издержки, поэтому недопотребление исключено.","Совокупная выгода превышает затраты на $15, но одного частного спроса может быть недостаточно.","Общественный чистый убыток составляет $35 на пациента.","Это обязательно чистое общественное благо, поскольку пользу получают и посторонние."],"options_uz":["Shaxsiy to‘lashga tayyorlik xarajatdan yuqori; demak, kam iste’mol bo‘lishi mumkin emas.","Jami foyda xarajatdan $15 yuqori, biroq faqat xususiy talab yetarli bo‘lmasligi mumkin.","Har bir bemor uchun sof ijtimoiy zarar $35.","Boshqalar ham foyda ko‘rgani uchun xizmat albatta sof jamoat ne’matidir."],"why":["Private benefit ($25) is below cost ($60), but total benefit ($25 + $50 = $75) exceeds it by $15. External benefits can lead to underprovision.","Личная выгода $25 ниже затрат $60, но общая выгода $25 + $50 = $75 выше их на $15. Внешние выгоды могут вести к недостаточному предложению.","Shaxsiy foyda $25 xarajat $60 dan past, lekin jami foyda $75 bo‘lib, xarajatdan $15 yuqori. Tashqi foyda xizmatning kam taqdim etilishiga sabab bo‘lishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-037","d":"hard","sec":190,"k":"D","en":"Beef and hides are jointly supplied. The hide market initially has demand Qd = 300 − 5P and supply Qs = 60 + 3P. Higher beef output increases hide supply to Qs = 100 + 3P with hide demand unchanged. How do the hide equilibrium price and quantity change?","ru":"Говядина и шкуры производятся совместно. На рынке шкур первоначально Qd = 300 − 5P, Qs = 60 + 3P. Рост производства говядины увеличивает предложение шкур до Qs = 100 + 3P, спрос на шкуры неизменен. Как изменятся равновесные цена и объём шкур?","uz":"Mol go‘shti va teri birgalikda ishlab chiqariladi. Teri bozorida dastlab Qd = 300 − 5P va Qs = 60 + 3P. Mol go‘shti ishlab chiqarish oshishi bilan teri taklifi Qs = 100 + 3P ga ko‘payadi, talab o‘zgarmaydi. Teri bozoridagi muvozanat narxi va miqdori qanday o‘zgaradi?","options_en":["Price −5, quantity +15","Price +5, quantity +25","Price −10, quantity +25","Price −5, quantity +25"],"options_ru":["Цена −5, объём +15","Цена +5, объём +25","Цена −10, объём +25","Цена −5, объём +25"],"options_uz":["Narx −5, miqdor +15","Narx +5, miqdor +25","Narx −10, miqdor +25","Narx −5, miqdor +25"],"why":["Originally P = 30 and Q = 150. After the joint-supply increase P = 25 and Q = 175. Price falls by 5, quantity rises by 25.","Сначала P = 30, Q = 150; после роста совместного предложения P = 25, Q = 175. Цена −5, объём +25.","Dastlab P = 30, Q = 150; birgalikdagi taklif oshgach P = 25, Q = 175. Narx −5, miqdor +25."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-040","d":"hard","sec":195,"k":"A","en":"The market price rises from $20 to $25, while quantity supplied rises from 80 to 100 units. Use initial values as the percentage-change base. What are PES and the change in sellers'' total sales receipts?","ru":"Рыночная цена растёт с $20 до $25, а объём предложения — с 80 до 100 единиц. Для процентных изменений используйте первоначальные значения. Найдите PES и изменение общей выручки продавцов.","uz":"Bozor narxi $20 dan $25 ga, taklif miqdori esa 80 dan 100 birlikka oshadi. Foizli o‘zgarishlar uchun boshlang‘ich qiymatlarni asos qilib oling. PES va sotuvchilarning jami tushumi o‘zgarishi qancha?","options_en":["PES = 1.0; receipts increase by $900","PES = 0.8; receipts increase by $400","PES = 1.25; receipts increase by $900","PES = 1.0; receipts decrease by $900"],"options_ru":["PES = 1,0; выручка увеличилась на $900","PES = 0,8; выручка увеличилась на $400","PES = 1,25; выручка увеличилась на $900","PES = 1,0; выручка уменьшилась на $900"],"options_uz":["PES = 1,0; tushum $900 ga oshdi","PES = 0,8; tushum $400 ga oshdi","PES = 1,25; tushum $900 ga oshdi","PES = 1,0; tushum $900 ga kamaydi"],"why":["PES = (20/80)/(5/20) = 1. Original receipts: $1,600; new receipts: $2,500, a $900 increase.","PES = (20/80)/(5/20) = 1. Первоначальная выручка $1 600, новая $2 500; прирост $900.","PES = (20/80)/(5/20) = 1. Dastlabki tushum $1600, yangi tushum $2500; farq $900."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-047","d":"hard","sec":180,"k":"C","en":"Market demand is Qd = 180 − 3P. A seller reduces price from $30 to $25 and sells exactly the quantities implied by this demand relationship. What is the change in total sales revenue?","ru":"Рыночный спрос описан Qd = 180 − 3P. Продавец снижает цену с $30 до $25 и продаёт ровно те объёмы, которые соответствуют этому уравнению спроса. Как изменится общая выручка?","uz":"Bozor talabi Qd = 180 − 3P. Sotuvchi narxni $30 dan $25 ga tushiradi va ushbu talab tenglamasidagi miqdorlarni sotadi. Jami tushum qanday o‘zgaradi?","options_en":["Increases by $75","Increases by $375","Decreases by $75","Remains unchanged"],"options_ru":["Увеличилась на $75","Увеличилась на $375","Уменьшилась на $75","Не изменилась"],"options_uz":["$75 ga oshdi","$375 ga oshdi","$75 ga kamaydi","O‘zgarmadi"],"why":["At P = 30, Q = 90 and revenue is $2,700. At P = 25, Q = 105 and revenue is $2,625. Revenue decreases by $75.","При P = 30 объём 90 и выручка $2 700. При P = 25 объём 105 и выручка $2 625. Снижение составляет $75.","P = 30 da Q = 90 va tushum $2700. P = 25 da Q = 105 va tushum $2625. Tushum $75 ga kamayadi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-051","d":"hard","sec":200,"k":"B","en":"Price rises from $15 to $18 as quantity demanded falls from 100 to 80 units. Using the midpoint formula, which combination best describes the absolute PED and the change in revenue?","ru":"Цена растёт с $15 до $18, объём спроса падает со 100 до 80 единиц. Используя формулу средней точки, выберите верную комбинацию модуля PED и изменения выручки.","uz":"Narx $15 dan $18 ga oshadi, talab miqdori 100 dan 80 birlikka kamayadi. O‘rta nuqta formulasi bo‘yicha PED moduli va tushumdagi o‘zgarish qaysi?","options_en":["PED ≈ 0.82; revenue rises by $60","PED ≈ 1.22; revenue falls by $60","PED ≈ 1.22; revenue rises by $60","PED ≈ 2.00; revenue falls by $300"],"options_ru":["PED ≈ 0,82; выручка увеличилась на $60","PED ≈ 1,22; выручка уменьшилась на $60","PED ≈ 1,22; выручка увеличилась на $60","PED ≈ 2,00; выручка уменьшилась на $300"],"options_uz":["PED ≈ 0,82; tushum $60 ga oshdi","PED ≈ 1,22; tushum $60 ga kamaydi","PED ≈ 1,22; tushum $60 ga oshdi","PED ≈ 2,00; tushum $300 ga kamaydi"],"why":["Absolute arc PED = (20/90)/(3/16.5) ≈ 1.22. Revenue falls from $1,500 to $1,440, or by $60.","Модуль дуговой PED = (20/90)/(3/16,5) ≈ 1,22. Выручка падает с $1 500 до $1 440, то есть на $60.","Yoy bo‘yicha PED moduli = (20/90)/(3/16,5) ≈ 1,22. Tushum $1500 dan $1440 ga, ya’ni $60 ga kamayadi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-065","d":"hard","sec":190,"k":"C","en":"Coffee demand starts at 500 packs. A 10% rise in tea''s price increases coffee demand with XED = +0.8. Subsequently coffee''s own price rises by 5%, and PED is −1.2. Apply each percentage change sequentially to the quantity reached at the preceding step. What is final coffee demand?","ru":"Первоначальный спрос на кофе — 500 упаковок. Подорожание чая на 10% повышает спрос на кофе при XED = +0,8. Затем собственная цена кофе растёт на 5%, а PED = −1,2. Применяйте каждый процентный эффект последовательно к результату предыдущего шага. Каков итоговый объём спроса на кофе?","uz":"Qahvaga dastlabki talab 500 qadoq. Choy narxi 10% oshganda XED = +0,8 bo‘yicha qahva talabi ortadi. So‘ng qahvaning o‘z narxi 5% oshadi, PED = −1,2. Har bir foizli o‘zgarishni oldingi bosqich natijasiga ketma-ket qo‘llang. Yakuniy talab qancha?","options_en":["470","510","507.6","540"],"options_ru":["470","510","507.6","540"],"options_uz":["470","510","507.6","540"],"why":["After the substitute-price effect: 500 × 1.08 = 540. Then the own-price effect reduces this by 6%: 540 × 0.94 = 507.6.","После изменения цены заменителя: 500 × 1,08 = 540. Затем собственная цена уменьшает объём на 6%: 540 × 0,94 = 507,6.","O‘rinbosar narxi ta’siridan keyin: 500 × 1,08 = 540. So‘ng o‘z narxi sabab 6% kamayadi: 540 × 0,94 = 507,6."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-008","d":"medium","sec":140,"k":"B","en":"Tomato demand is Qd = 120 − 2P and initial supply is Qs = 30 + P. Irrigation improvements shift supply to Qs = 42 + P while demand stays unchanged. How much does equilibrium price fall?","ru":"Спрос на томаты Qd = 120 − 2P, первоначальное предложение Qs = 30 + P. Улучшение орошения изменяет предложение до Qs = 42 + P при неизменном спросе. На сколько снизится равновесная цена?","uz":"Pomidor talabi Qd = 120 − 2P, dastlabki taklif Qs = 30 + P. Sug‘orish yaxshilanib, taklif Qs = 42 + P ga o‘zgardi, talab esa o‘zgarmadi. Muvozanat narxi qanchaga pasayadi?","options_en":["2","4","6","12"],"options_ru":["2","4","6","12"],"options_uz":["2","4","6","12"],"why":["Initial price is 30; after the supply shift it is 26. The fall is 4.","Изначально равновесная цена 30, после сдвига — 26. Снижение равно 4.","Dastlabki muvozanat narxi 30, keyin 26 bo‘ladi. Pasayish 4 ga teng."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-010","d":"medium","sec":125,"k":"D","en":"Only two flats can be allocated. Four households are willing and able to pay at most $120, $95, $80 and $55 for one flat each. If the price mechanism allocates the flats to those valuing them most, what is the combined willingness to pay of the successful buyers?","ru":"Можно распределить только две квартиры. Четыре домохозяйства готовы и способны заплатить максимум $120, $95, $80 и $55 за одну квартиру каждое. Если ценовой механизм распределяет квартиры среди покупателей с наибольшей оценкой, какова их суммарная готовность платить?","uz":"Faqat ikkita xonadonni taqsimlash mumkin. To‘rt uy xo‘jaligining har biri bir xonadon uchun eng ko‘pi bilan $120, $95, $80 va $55 to‘lashga tayyor hamda qodir. Narx mexanizmi xonadonlarni eng yuqori baholovchilarga ajratsa, ularning umumiy to‘lashga tayyorligi qancha?","options_en":["$175","$200","$255","$215"],"options_ru":["$175","$200","$255","$215"],"options_uz":["$175","$200","$255","$215"],"why":["The two highest bidders receive the flats, with valuations $120 and $95. Combined willingness to pay is $215.","Две квартиры получают покупатели с оценками $120 и $95. Совокупная готовность платить равна $215.","Eng yuqori ikkita bahoga ($120 va $95) ega xaridorlar xonadon oladi. Jami to‘lashga tayyorlik $215."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-012","d":"medium","sec":140,"k":"A","en":"A shirt factory raises production from 1,000 to 1,200 shirts, but a new process reduces cotton use from 2 kg to 1.5 kg per shirt. If all cotton is sourced domestically, how does the factory''s quantity demanded of cotton change?","ru":"Фабрика увеличивает выпуск рубашек с 1 000 до 1 200, но новая технология снижает расход хлопка с 2 до 1,5 кг на рубашку. Если весь хлопок закупается внутри страны, как изменится объём спроса фабрики на хлопок?","uz":"Ko‘ylak fabrikasi ishlab chiqarishni 1000 tadan 1200 taga oshiradi, ammo yangi usul har ko‘ylakka paxta sarfini 2 kg dan 1,5 kg ga tushiradi. Paxtaning barchasi mahalliy xarid qilinsa, fabrikaning paxtaga talabi qanday o‘zgaradi?","options_en":["Falls by 10%","Rises by 20%","Rises by 8%","Remains unchanged"],"options_ru":["Снизится на 10%","Вырастет на 20%","Вырастет на 8%","Не изменится"],"options_uz":["10% ga kamayadi","20% ga oshadi","8% ga oshadi","O‘zgarmaydi"],"why":["Originally 1,000 × 2 = 2,000 kg; afterwards 1,200 × 1.5 = 1,800 kg, 10% less despite greater shirt output.","Первоначально требуется 1 000 × 2 = 2 000 кг, после изменения — 1 200 × 1,5 = 1 800 кг. Спрос на хлопок падает на 10%.","Dastlab 1000 × 2 = 2000 kg, keyin 1200 × 1,5 = 1800 kg. Paxtaga talab 10% ga kamayadi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-017","d":"medium","sec":140,"k":"C","en":"Tea prices rise, shifting demand for substitute coffee from Qd = 100 − 2P to Qd = 120 − 2P. Coffee supply remains Qs = 20 + 2P. By how much does coffee''s equilibrium quantity increase?","ru":"Цены на чай растут, поэтому спрос на кофе как заменитель изменяется с Qd = 100 − 2P до Qd = 120 − 2P. Предложение кофе остаётся Qs = 20 + 2P. На сколько увеличится равновесный объём кофе?","uz":"Choy narxi oshgani uchun uning o‘rinbosari qahvaga talab Qd = 100 − 2P dan Qd = 120 − 2P ga siljiydi. Qahva taklifi Qs = 20 + 2P bo‘lib qoladi. Qahvaning muvozanat miqdori qanchaga oshadi?","options_en":["5","20","10","40"],"options_ru":["5","20","10","40"],"options_uz":["5","20","10","40"],"why":["Initial equilibrium P = 20, Q = 60; after demand shifts P = 25, Q = 70. Quantity rises by 10.","Сначала P = 20, Q = 60; после сдвига P = 25, Q = 70. Прирост объёма равен 10.","Avval P = 20, Q = 60; talab siljigach P = 25, Q = 70. Miqdor 10 ga oshadi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-018","d":"medium","sec":120,"k":"A","en":"A school has 30 computers. Up to 25 can be used for programming, where each occupied computer produces 4 educational benefit points. Up to 20 can be used for statistics, where each produces 3 points. Each computer can serve one learner only. How should the school allocate computers to maximise the stated total benefit?","ru":"У школы 30 компьютеров. На занятиях по программированию можно использовать до 25 компьютеров, каждый приносит 4 условных балла учебной пользы. На статистике можно использовать до 20, каждый приносит 3 балла. Один компьютер обслуживает одного ученика. Как распределить компьютеры для максимальной указанной пользы?","uz":"Maktabda 30 ta kompyuter bor. Dasturlash darsida ko‘pi bilan 25 tasi ishlatilishi mumkin, har biri 4 foyda balli beradi. Statistika darsida ko‘pi bilan 20 tasi ishlatiladi, har biri 3 ball beradi. Har kompyuter bitta o‘quvchiga xizmat qiladi. Jami foydani maksimallashtirish uchun qanday taqsimlash kerak?","options_en":["25 programming; 5 statistics","15 programming; 15 statistics","10 programming; 20 statistics","20 programming; 10 statistics"],"options_ru":["25 — программированию; 5 — статистике","15 — программированию; 15 — статистике","10 — программированию; 20 — статистике","20 — программированию; 10 — статистике"],"options_uz":["25 tasi dasturlashga; 5 tasi statistikaga","15 tasi dasturlashga; 15 tasi statistikaga","10 tasi dasturlashga; 20 tasi statistikaga","20 tasi dasturlashga; 10 tasi statistikaga"],"why":["Programming yields 4 points per computer versus 3 in statistics; allocate the first 25 to programming, then the remaining 5 to statistics (115 points).","Компьютер в программировании даёт 4 балла против 3 в статистике. Первые 25 следует выделить программированию, ещё 5 — статистике; всего 115 баллов.","Dasturlashda har kompyuter 4 ball, statistikada 3 ball beradi. Dasturlashga 25 ta, qolgan 5 tasini statistikaga ajratish jami 115 ball beradi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-023","d":"medium","sec":130,"k":"B","en":"A café owner commits her savings, organises staff and suppliers and accepts any residual profit or loss. A salaried manager follows her business plan. Which factor-of-production distinction is best?","ru":"Владелица кафе вкладывает сбережения, организует персонал и поставщиков и несёт риск остаточной прибыли или убытка. Наёмный управляющий исполняет её бизнес-план. Какое различие факторов производства наиболее корректно?","uz":"Kafe egasi jamg‘armasini tikadi, xodimlar va yetkazib beruvchilarni boshqaradi hamda qolgan foyda yoki zararni o‘z zimmasiga oladi. Yollangan menejer uning rejasini bajaradi. Ishlab chiqarish omillarini qanday ajratish to‘g‘ri?","options_en":["Both provide only physical capital.","The owner supplies enterprise/risk-bearing, while the manager supplies labour.","The manager automatically owns the entrepreneurial profit.","Ownership of savings means the owner supplies land, not enterprise."],"options_ru":["Оба предоставляют только физический капитал.","Владелица предоставляет предпринимательскую функцию и принимает риск, а управляющий — труд.","Наёмный управляющий автоматически получает предпринимательскую прибыль.","Наличие сбережений означает предоставление земли, а не предпринимательства."],"options_uz":["Ikkalasi faqat jismoniy kapital beradi.","Egasi tadbirkorlik va tavakkalchilikni, menejer esa mehnatni taqdim etadi.","Yollangan menejer avtomatik tarzda tadbirkorlik foydasiga ega bo‘ladi.","Jamg‘arma egasi bo‘lish yer omilini, tadbirkorlikni emas, anglatadi."],"why":["Enterprise involves coordination and residual risk; routine paid management is labour even when it includes decisions.","Предприниматель принимает остаточный риск и координирует ресурсы; оплачиваемое управление относится к труду.","Tadbirkorlik koordinatsiya va qolgan tavakkalchilikni o‘z ichiga oladi; maoshli boshqaruv esa mehnat hisoblanadi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-026","d":"medium","sec":120,"k":"C","en":"Demand for copper rises unexpectedly and its price increases. Which response best illustrates the price mechanism''s incentive rather than its signalling function?","ru":"Спрос на медь неожиданно вырос, вслед за ним повысилась цена. Какое действие лучше показывает стимулирующую, а не информационную функцию ценового механизма?","uz":"Misga talab kutilmaganda oshib, narx ko‘tarildi. Qaysi javob narx mexanizmining axborot berish emas, balki rag‘batlantirish vazifasini yaxshiroq ko‘rsatadi?","options_en":["Producers infer copper is scarcer relative to demand.","Consumers learn that copper is more expensive.","Mining firms invest in output expansion because potential revenues are higher.","Retailers observe the new market price."],"options_ru":["Производители узнают о выросшей относительной редкости меди.","Покупатели узнают о подорожании меди.","Добывающие фирмы инвестируют в расширение выпуска в расчёте на более высокую выручку.","Торговцы наблюдают новую рыночную цену."],"options_uz":["Ishlab chiqaruvchilar misning talabga nisbatan kamyoblashganini bilib oladilar.","Iste’molchilar mis qimmatlashganini biladilar.","Kon korxonalari daromad ehtimoli oshgani uchun ishlab chiqarishni kengaytirishga sarmoya kiritadi.","Sotuvchilar yangi bozor narxini ko‘radilar."],"why":["A signal communicates scarcity; an incentive changes producers'' decisions. Expansion motivated by higher expected returns is the incentive.","Сигнал сообщает о редкости ресурса, стимул меняет поведение. Инвестиция ради ожидаемого дохода — стимулирующая функция.","Signal tanqislik haqida xabar beradi, rag‘bat esa qarorni o‘zgartiradi. Yuqori daromad umididagi investitsiya — rag‘bat vazifasi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-027","d":"medium","sec":140,"k":"A","en":"A bakery pays $1,000 rent for its premises, $2,000 wages and $150 interest on a business loan. Which list matches all three payments to factors of production?","ru":"Пекарня платит $1 000 аренды помещения, $2 000 зарплаты и $150 процентов по кредиту на бизнес. Какая комбинация верно соотносит все три платежа с факторами производства?","uz":"Nonvoyxona binoga $1000 ijara, xodimlarga $2000 ish haqi va biznes kreditiga $150 foiz to‘laydi. Uchala to‘lov ishlab chiqarish omillariga qanday mos keladi?","options_en":["Rent—land; wages—labour; interest—capital","Rent—labour; wages—land; interest—enterprise","Rent—capital; wages—enterprise; interest—land","Rent—land; wages—capital; interest—labour"],"options_ru":["Аренда — земля; зарплата — труд; процент — капитал","Аренда — труд; зарплата — земля; процент — предпринимательство","Аренда — капитал; зарплата — предпринимательство; процент — земля","Аренда — земля; зарплата — капитал; процент — труд"],"options_uz":["Ijara — yer; ish haqi — mehnat; foiz — kapital","Ijara — mehnat; ish haqi — yer; foiz — tadbirkorlik","Ijara — kapital; ish haqi — tadbirkorlik; foiz — yer","Ijara — yer; ish haqi — kapital; foiz — mehnat"],"why":["In conventional factor rewards, rent rewards land, wages reward labour, and interest rewards capital.","В стандартной классификации аренда — доход земли, зарплата — труда, процент — капитала.","Odatdagi tasnifda ijara yer, ish haqi mehnat, foiz esa kapital daromadidir."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-028","d":"medium","sec":125,"k":"C","en":"A hospital makes two separate choices. First, it decides to fund more preventive screenings rather than emergency operations. Second, it switches from manual record-keeping to an electronic workflow for the chosen services. Which pair classifies these decisions in order?","ru":"Больница принимает два отдельных решения. Сначала она выделяет больше средств профилактическим обследованиям, чем экстренным операциям. Затем меняет бумажный учёт на электронный способ оказания выбранных услуг. Как по порядку классифицировать оба решения?","uz":"Shifoxona ikkita alohida qaror qiladi. Avval favqulodda operatsiyalarga nisbatan profilaktik tekshiruvlarni ko‘proq moliyalashtirishni tanlaydi. So‘ng tanlangan xizmatlarda qog‘ozli qaydlarni elektron jarayon bilan almashtiradi. Bu ikki qaror ketma-ket qaysi savollarga tegishli?","options_en":["How to produce; for whom to produce","For whom to produce; what to produce","What to produce; how to produce","What to produce; for whom to produce"],"options_ru":["Как производить; для кого производить","Для кого производить; что производить","Что производить; как производить","Что производить; для кого производить"],"options_uz":["Qanday ishlab chiqarish; kim uchun ishlab chiqarish","Kim uchun ishlab chiqarish; nima ishlab chiqarish","Nima ishlab chiqarish; qanday ishlab chiqarish","Nima ishlab chiqarish; kim uchun ishlab chiqarish"],"why":["The first choice sets the mix of outputs (''what''); the second changes the technique for producing them (''how'').","Первое решение определяет состав услуг («что»), второе — способ оказания («как»).","Birinchi qaror xizmatlar tarkibini («nima»), ikkinchisi esa ularni bajarish usulini («qanday») belgilaydi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-030","d":"medium","sec":150,"k":"B","en":"Ticket demand is Qd = 100 − 2P and supply is Qs = 20 + 2P. Tickets are initially offered at price P = 10. How large is the shortage at that price, and in which direction would price tend to move in a flexible market?","ru":"Спрос на билеты Qd = 100 − 2P, предложение Qs = 20 + 2P. Первоначальная цена P = 10. Каков дефицит билетов при этой цене и в какую сторону обычно движется цена на гибком рынке?","uz":"Chipta talabi Qd = 100 − 2P, taklifi Qs = 20 + 2P. Dastlabki narx P = 10. Shu narxda taqchillik qancha va erkin bozorda narx qaysi tomonga intiladi?","options_en":["Shortage 20; price tends to fall","Shortage 40; price tends to rise","Surplus 40; price tends to fall","Shortage 60; price tends to rise"],"options_ru":["Дефицит 20; цена стремится вниз","Дефицит 40; цена стремится вверх","Излишек 40; цена стремится вниз","Дефицит 60; цена стремится вверх"],"options_uz":["Taqchillik 20; narx pasayishga intiladi","Taqchillik 40; narx oshishga intiladi","Ortiqcha taklif 40; narx pasayishga intiladi","Taqchillik 60; narx oshishga intiladi"],"why":["At P = 10, demand is 80 and supply 40, yielding a shortage of 40. Excess demand creates upward pressure on price.","При P = 10 спрос 80, предложение 40; дефицит 40. Избыточный спрос создаёт давление на повышение цены.","P = 10 da talab 80, taklif 40; taqchillik 40. Ortiqcha talab narxni oshirishga undaydi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-031","d":"medium","sec":140,"k":"C","en":"An economy observes that income rises by 8% and demand for product A rises by 12%, while demand for product B falls by 4%. Other factors do not change. Which pair gives the income elasticities for A and B?","ru":"Доходы растут на 8%; спрос на товар A увеличивается на 12%, а спрос на товар B падает на 4%. Прочие условия неизменны. Какие значения эластичности спроса по доходу у товаров A и B?","uz":"Daromad 8% ga oshadi; A mahsulotga talab 12% ga oshadi, B mahsulotga talab 4% ga kamayadi. Boshqa omillar o‘zgarmaydi. A va B ning daromad elastikliklari qanday?","options_en":["A = +0.67; B = −2.0","A = +1.5; B = +0.5","A = +1.5; B = −0.5","A = −1.5; B = +0.5"],"options_ru":["A = +0.67; B = −2.0","A = +1.5; B = +0.5","A = +1.5; B = −0.5","A = −1.5; B = +0.5"],"options_uz":["A = +0.67; B = −2.0","A = +1.5; B = +0.5","A = +1.5; B = −0.5","A = −1.5; B = +0.5"],"why":["YED(A) = +12%/+8% = +1.5; YED(B) = −4%/+8% = −0.5.","YED(A) = +12%/+8% = +1,5; YED(B) = −4%/+8% = −0,5.","YED(A) = +12%/+8% = +1,5; YED(B) = −4%/+8% = −0,5."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-032","d":"medium","sec":135,"k":"D","en":"A bakery buys an automated kneading machine and trains workers to use it. Which classification AND likely long-run production effect are consistent with the two investments?","ru":"Пекарня покупает автоматическую тестомесильную машину и обучает работников её использовать. Какая классификация вместе с возможным долгосрочным эффектом соответствует обоим вложениям?","uz":"Nonvoyxona avtomatik xamir qorish mashinasini oladi va ishchilarni undan foydalanishga o‘qitadi. Ikkala investitsiyaning tasnifi va uzoq muddatli ehtimoliy ta’siri qaysi javobda mos?","options_en":["Both are land; productive capacity must fall.","The machine is human capital, training is physical capital; capacity is unchanged.","Both are labour; only current demand can rise.","The machine adds physical capital and training adds human capital; productive capacity may rise."],"options_ru":["Оба вложения — земля; производственный потенциал обязательно снизится.","Машина — человеческий капитал, обучение — физический; потенциал неизменен.","Оба — труд; может увеличиться только текущий спрос.","Машина добавляет физический капитал, обучение — человеческий; производственный потенциал может вырасти."],"options_uz":["Ikkalasi yer omili; ishlab chiqarish quvvati albatta kamayadi.","Mashina inson kapitali, o‘qitish jismoniy kapital; quvvat o‘zgarmaydi.","Ikkalasi mehnat; faqat joriy talab oshishi mumkin.","Mashina jismoniy kapitalni, o‘qitish inson kapitalini oshiradi; ishlab chiqarish quvvati ortishi mumkin."],"why":["Equipment is physical capital and acquired skills are human capital; both can raise productive potential.","Оборудование — физический капитал, приобретённые навыки — человеческий; оба вложения способны увеличить потенциальный выпуск.","Uskuna jismoniy kapital, malaka oshishi esa inson kapitali; har ikkisi potensial ishlab chiqarishni ko‘paytirishi mumkin."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-034","d":"medium","sec":135,"k":"D","en":"A city can finance only one project: a flood barrier worth $11m to residents, a library worth $9m or two playgrounds worth $8m in total. All cost the same limited budget and values are comparable. If the barrier is chosen, what is the opportunity cost in forgone benefit?","ru":"Город может оплатить лишь один проект: дамбу с выгодой $11 млн, библиотеку с выгодой $9 млн либо две площадки с суммарной выгодой $8 млн. Бюджет каждого одинаков, оценки сопоставимы. Если выбирается дамба, какова альтернативная стоимость в единицах отвергнутой выгоды?","uz":"Shahar faqat bitta loyihani moliyalashtira oladi: $11 mln foydali toshqin to‘sig‘i, $9 mln foydali kutubxona yoki jami $8 mln foydali ikki maydoncha. Xarajatlari bir xil, foydalar taqqoslanadi. To‘siq tanlansa, voz kechilgan foyda bo‘yicha muqobil qiymat qancha?","options_en":["$11 million","$8 million","$2 million","$9 million"],"options_ru":["$11 млн","$8 млн","$2 млн","$9 млн"],"options_uz":["$11 mln","$8 mln","$2 mln","$9 mln"],"why":["The next-best feasible project is the $9m library, so the opportunity cost is $9m of forgone benefit.","Лучший отвергнутый проект — библиотека с выгодой $9 млн, поэтому альтернативная стоимость — $9 млн.","Eng yaxshi voz kechilgan muqobil $9 mln foydali kutubxona; muqobil qiymat $9 mln."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-035","d":"medium","sec":135,"k":"C","en":"A village has abundant untreated spring water available without a scarcity cost at the source, but a nearby city needs scarce labour, filters and vehicles to make and deliver safe drinking water. Which statement correctly interprets the status of water in these two settings?","ru":"В деревне необработанная родниковая вода доступна у источника без альтернативной стоимости, но соседнему городу нужны ограниченные труд, фильтры и транспорт, чтобы очищать и доставлять безопасную воду. Какое утверждение правильно описывает экономический статус воды в двух условиях?","uz":"Qishloqda buloqning tozalanmagan suvi manbada tanqislik xarajatisiz mavjud, ammo yaqin shaharga xavfsiz suvni tozalash va yetkazish uchun cheklangan mehnat, filtr hamda transport kerak. Ikki sharoitda suvning iqtisodiy maqomi qanday?","options_en":["Water is always a free good regardless of treatment or delivery.","Only the city’s water is a free good because it is sold.","Water at the village source may be free, while delivered safe water in the city is an economic good.","Water at the village source becomes an economic good solely because the city exists."],"options_ru":["Вода всегда свободное благо, независимо от очистки и доставки.","Только городская вода свободна, поскольку продаётся.","Вода у деревенского источника может быть свободным благом, а доставленная безопасная вода в городе — экономическим.","Вода у деревенского источника становится экономическим благом лишь потому, что существует город."],"options_uz":["Suv tozalash yoki yetkazishdan qat’i nazar har doim erkin ne’mat.","Faqat shahardagi suv erkin ne’mat, chunki u sotiladi.","Qishloq manbasidagi suv erkin bo‘lishi mumkin, shaharga yetkazilgan xavfsiz suv esa iqtisodiy ne’mat.","Shahar mavjudligi sababli qishloq manbasidagi suv ham avtomatik iqtisodiy ne’mat bo‘ladi."],"why":["Scarcity and opportunity cost depend on the setting and production process: treating and delivering safe water uses scarce inputs, even when raw water at its source is abundant.","Ограниченность зависит от условий: очистка и доставка безопасной воды расходуют редкие ресурсы, даже если исходная вода у источника изобильна.","Tanqislik sharoitga bog‘liq: suvni tozalash va yetkazish cheklangan resurslarni ishlatadi, manbadagi xom suv mo‘l bo‘lsa ham."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-038","d":"medium","sec":160,"k":"B","en":"A bakery can make the same 200 loaves using method A (16 labour-hours and 6 machine-hours) or method B (8 labour-hours and 12 machine-hours). Labour costs $20 per hour and machine use $20 per hour. Which method costs less, and by how much?","ru":"Пекарня может выпустить одинаковые 200 буханок способом A (16 человеко-часов и 6 машино-часов) либо способом B (8 человеко-часов и 12 машино-часов). Один час труда стоит $20, один машино-час — $20. Какой способ дешевле и на сколько?","uz":"Nonvoyxona bir xil 200 ta nonni A usulida (16 ishchi-soat va 6 mashina-soat) yoki B usulida (8 ishchi-soat va 12 mashina-soat) ishlab chiqarishi mumkin. Mehnatning bir soati $20, mashinaning bir soati $20. Qaysi usul arzonroq va qancha?","options_en":["Method A, by $40","Method B, by $40","Method B, by $80","Both cost the same"],"options_ru":["Способ A дешевле на $40","Способ B дешевле на $40","Способ B дешевле на $80","Стоимость одинакова"],"options_uz":["A usuli $40 ga arzon","B usuli $40 ga arzon","B usuli $80 ga arzon","Narx bir xil"],"why":["Method A costs (16 + 6) × $20 = $440; method B costs (8 + 12) × $20 = $400. Choosing how to produce saves $40 with method B.","Способ A: (16 + 6) × $20 = $440; способ B: (8 + 12) × $20 = $400. Выбор способа производства B экономит $40.","A usuli: (16 + 6) × $20 = $440; B usuli: (8 + 12) × $20 = $400. B usulini tanlash $40 tejaydi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-041","d":"medium","sec":135,"k":"A","en":"Before specialisation, three workers each make 12 units per day. After dividing tasks, total daily output rises to 42 units with the same staff and working hours. Approximately how much has output per worker increased in percentage terms?","ru":"До специализации три работника выпускают по 12 изделий в день. После разделения труда суммарный дневной выпуск при том же штате и времени вырос до 42 изделий. На сколько примерно процентов вырос выпуск на работника?","uz":"Ixtisoslashuvdan oldin uch ishchining har biri kuniga 12 tadan mahsulot tayyorlaydi. Vazifalar bo‘lingach, shu ishchilar va ish vaqtida jami ishlab chiqarish 42 taga yetdi. Bir ishchiga to‘g‘ri keladigan ishlab chiqarish taxminan necha foiz oshdi?","options_en":["16.7%","14.0%","42.0%","6.0%"],"options_ru":["16.7%","14.0%","42.0%","6.0%"],"options_uz":["16.7%","14.0%","42.0%","6.0%"],"why":["Output per worker rises from 12 to 42/3 = 14, an increase of 2/12 ≈ 16.7%.","Выпуск на работника вырос с 12 до 42/3 = 14: прирост 2/12 ≈ 16,7%.","Bir ishchiga ishlab chiqarish 12 tadan 42/3 = 14 taga oshdi: 2/12 ≈ 16,7%."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-043","d":"medium","sec":130,"k":"D","en":"A tidal power station uses natural currents, manufactured turbines and hired engineers. How should these three inputs be classified as factors of production in that order?","ru":"Приливная электростанция использует природные течения, изготовленные турбины и наёмных инженеров. Как классифицируются эти три фактора производства по порядку?","uz":"Suv ko‘tarilishidan elektr oluvchi stansiya tabiiy oqimlar, ishlab chiqarilgan turbinalar va yollangan muhandislardan foydalanadi. Ushbu uch omil ketma-ket qanday tasniflanadi?","options_en":["Capital; land; enterprise","Labour; capital; land","Land; labour; capital","Land; capital; labour"],"options_ru":["Капитал; земля; предпринимательство","Труд; капитал; земля","Земля; труд; капитал","Земля; капитал; труд"],"options_uz":["Kapital; yer; tadbirkorlik","Mehnat; kapital; yer","Yer; mehnat; kapital","Yer; kapital; mehnat"],"why":["Natural currents are land, turbines are physical capital, and engineers provide labour.","Природные течения — земля, турбины — физический капитал, инженеры — труд.","Tabiiy oqimlar yer, turbinalar jismoniy kapital, muhandislar mehnat omilidir."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-045","d":"medium","sec":150,"k":"C","en":"An economy has a straight-line PPC between 80 tonnes of rice and zero cloth, and zero rice and 40 rolls of cloth. If it raises cloth production from 20 to 30 rolls while staying on the PPC, how many tonnes of rice must it give up?","ru":"Линейная КПВ проходит через 80 тонн риса и 0 рулонов ткани, а также через 0 риса и 40 рулонов ткани. Если производство ткани вырастет с 20 до 30 рулонов при движении по КПВ, от скольких тонн риса придётся отказаться?","uz":"Iqtisodiyotning chiziqli IIECsida 80 tonna guruch va 0 o‘ram mato hamda 0 guruch va 40 o‘ram mato nuqtalari bor. IIEC bo‘ylab mato ishlab chiqarish 20 dan 30 o‘ramga oshsa, necha tonna guruchdan voz kechiladi?","options_en":["10","40","20","5"],"options_ru":["10","40","20","5"],"options_uz":["10","40","20","5"],"why":["Each extra cloth roll costs 80/40 = 2 tonnes of rice; 10 extra rolls cost 20 tonnes.","Каждый дополнительный рулон ткани стоит 80/40 = 2 тонны риса; 10 рулонов требуют отказаться от 20 тонн.","Har qo‘shimcha mato o‘rami 80/40 = 2 tonna guruch turadi; 10 o‘ram uchun 20 tonna guruchdan voz kechiladi."]},{"ref":"EC9708:G2:EC9708-G2-T1-P-050","d":"medium","sec":120,"k":"B","en":"A car park has five available spaces. Six drivers each want at most one and are willing to pay $100, $90, $80, $70, $60 and $50 respectively. What is quantity demanded at the price of $70 and then at the lower price of $60?","ru":"На стоянке пять доступных мест. Шесть водителей хотят не более одного места и готовы заплатить $100, $90, $80, $70, $60 и $50 соответственно. Каков спрос при цене $70, а затем при снижении до $60?","uz":"Avtoturargohda beshta joy bor. Olti haydovchi bittadan ortiq joy xohlamaydi va $100, $90, $80, $70, $60 hamda $50 to‘lashga tayyor. $70 narxda va narx $60 ga tushirilganda talab nechta?","options_en":["5 then 4","4 then 5","4 then 6","5 then 6"],"options_ru":["5, затем 4","4, затем 5","4, затем 6","5, затем 6"],"options_uz":["5, so‘ng 4","4, so‘ng 5","4, so‘ng 6","5, so‘ng 6"],"why":["Four valuations are at least $70 and five are at least $60, so quantity demanded rises from four to five.","При цене $70 готовы купить четверо, при $60 — пятеро. Объём спроса растёт с четырёх до пяти.","$70 narxda to‘rtta, $60 narxda beshta xaridor bor. Talab 4 tadan 5 taga oshadi."]}]'::jsonb;
  item jsonb; v_old bigint; v_new bigint; v_pool bigint; v_order int; v_count int;
  v_correct text; v_i int; v_why_en text; v_why_ru text; v_why_uz text; v_old_key text;
  v_saved_answers int;
BEGIN
  IF jsonb_array_length(payload) <> 39 THEN RAISE EXCEPTION 'expected_39_replacements'; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l
    JOIN public.practice_pools p ON p.id=l.pool_id WHERE p.subject_id=7 AND p.tour_no=1 AND l.is_active;
  IF v_count <> 70 THEN RAISE EXCEPTION 'T1_pool_not_70_before: %',v_count; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(payload)
  LOOP
    v_old_key := item->>'ref'; v_correct := item->>'k';
    IF jsonb_array_length(item->'options_en')<>4 OR jsonb_array_length(item->'options_ru')<>4 OR jsonb_array_length(item->'options_uz')<>4 THEN
      RAISE EXCEPTION 'four_options_required: %',v_old_key;
    END IF;
    IF v_correct NOT IN ('A','B','C','D') OR item->>'d' NOT IN ('medium','hard') THEN RAISE EXCEPTION 'invalid_authoring: %',v_old_key; END IF;
    SELECT q.id INTO STRICT v_old FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=v_old_key;
    SELECT count(*) INTO v_saved_answers FROM public.practice_answers a WHERE a.question_id=v_old;
    IF v_saved_answers > 0 THEN RAISE EXCEPTION 'review_history_bearing_question_before_replacement: %',v_old_key; END IF;
    SELECT l.pool_id,l.order_no INTO STRICT v_pool,v_order FROM public.practice_pool_questions l
      JOIN public.practice_pools p ON p.id=l.pool_id
      WHERE l.question_id=v_old AND l.is_active AND p.subject_id=7 AND p.tour_no=1;
    SELECT id INTO v_new FROM public.questions WHERE subject_id=7 AND book_ref=v_old_key||'-V2';
    IF v_new IS NOT NULL THEN RAISE EXCEPTION 'already_exists: %',v_old_key; END IF;
    v_i := ascii(v_correct)-64;
    v_why_en := item->'why'->>0; v_why_ru := item->'why'->>1; v_why_uz := item->'why'->>2;
    INSERT INTO public.questions (
      subject_id,topic,subtopic,difficulty,qtype,
      question_text,options_text,correct_answer,explanation,image_url,is_active,
      question_text_ru,question_text_uz,question_text_en,
      options_text_ru,options_text_uz,options_text_en,
      explanation_ru,explanation_uz,explanation_en,
      book_ref,time_limit_sec,quality_flag,quality_status
    )
    SELECT
      src.subject_id,src.topic,src.subtopic,item->>'d','mcq',
      item->>'en',(item->'options_en')::text,v_correct,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      NULL,true,item->>'ru',item->>'uz',item->>'en',
      (item->'options_ru')::text,(item->'options_uz')::text,(item->'options_en')::text,
      'Правильный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nПочему: '||v_why_ru,
      'To‘g‘ri javob: '||(item->'options_uz'->>(v_i-1))||E'\nSabab: '||v_why_uz,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      v_old_key||'-V2',(item->>'sec')::int,src.quality_flag,'published'
    FROM public.questions src WHERE src.id=v_old
    RETURNING id INTO v_new;
    UPDATE public.practice_pool_questions SET is_active=false
      WHERE pool_id=v_pool AND question_id=v_old AND is_active;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count<>1 THEN RAISE EXCEPTION 'old_link_not_one: %',v_old_key; END IF;
    INSERT INTO public.practice_pool_questions (pool_id,question_id,order_no,is_active)
      VALUES (v_pool,v_new,v_order,true);
    INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
      VALUES(v_old,v_new,'replacement','Economics Gen2: actual editorial difficulty upgrade, T1 governed practice, originals retained');
    FOR v_i IN 1..4 LOOP
      INSERT INTO public.question_answer_diagnostics(
        question_id,answer_kind,answer_key,answer_value,is_correct,
        mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,
        next_action_ru,next_action_uz,next_action_en,rule_json,quality_status
      )
      SELECT v_new,'mcq_option',chr(64+v_i),NULL,(chr(64+v_i)=v_correct),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'multi_step_economic_reasoning' END,
        src.subtopic,
        'Выбранный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nОбъяснение: '||v_why_ru||E'\nПравильный ответ: '||(item->'options_ru'->>(ascii(v_correct)-65)),
        'Tanlangan javob: '||(item->'options_uz'->>(v_i-1))||E'\nIzoh: '||v_why_uz||E'\nTo‘g‘ri javob: '||(item->'options_uz'->>(ascii(v_correct)-65)),
        'Selected answer: '||(item->'options_en'->>(v_i-1))||E'\nReason: '||v_why_en||E'\nCorrect answer: '||(item->'options_en'->>(ascii(v_correct)-65)),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Повторите метод решения и проверьте каждый шаг.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Yechim usulini takrorlang va har bir bosqichni tekshiring.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Review the method and check each step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_T1P'||substring(v_old_key from 'P-([0-9]{3})')||'_V2_'||chr(64+v_i)),
        'published'
      FROM public.questions src WHERE src.id=v_old;
    END LOOP;
  END LOOP;
  -- Existing unchanged T1 items receive academically reviewed metadata, not fabricated all-medium labels.
  UPDATE public.questions q SET difficulty=CASE
    WHEN right(q.book_ref,3) IN ('004','006','009','015','019','021','048','049','054','060','070') THEN 'medium'
    ELSE 'easy' END
    WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T1-P-[0-9]{3}$'
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(payload) j WHERE j->>'ref'=q.book_ref);
  GET DIAGNOSTICS v_count=ROW_COUNT;
  IF v_count<>31 THEN RAISE EXCEPTION 'unchanged_count_expected31: %',v_count; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    WHERE p.subject_id=7 AND p.tour_no=1 AND l.is_active;
  IF v_count<>70 THEN RAISE EXCEPTION 'active_pool_not70_after: %',v_count; END IF;
  IF EXISTS (
    SELECT 1 FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
       JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=1 AND l.is_active
    GROUP BY 1 HAVING count(*)<>70
  ) THEN RAISE EXCEPTION 'pool_count_inconsistent'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=1 AND l.is_active AND q.difficulty='easy') <> 20
    THEN RAISE EXCEPTION 'difficulty_easy_not20'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=1 AND l.is_active AND q.difficulty='medium') <> 30
    THEN RAISE EXCEPTION 'difficulty_medium_not30'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=1 AND l.is_active AND q.difficulty='hard') <> 20
    THEN RAISE EXCEPTION 'difficulty_hard_not20'; END IF;
END $reb$;
COMMIT;
